result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_astar.py", "content": "import pytest

from collections import deque

from astar import astar, neighbors, parse_grid


def bfs_distance(rows):
    """Shortest 4-connected path length (number of moves), or None."""
    grid, s, g = parse_grid(rows)
    dist = {s: 0}
    q = deque([s])
    while q:
        cur = q.popleft()
        if cur == g:
            return dist[cur]
        for nb in neighbors(grid, cur):
            if nb not in dist:
                dist[nb] = dist[cur] + 1
                q.append(nb)
    return None


def path_cost(path):
    return len(path) - 1 if path else None


MAP_SUBOPTIMAL = [
    # The open column under S tempts the 1.5*Euclidean heuristic straight
    # down, but the walls at rows 4-5 block the direct approach; the real
    # shortest route swings left through the top corridor first.
    "..S#",
    ".#..",
    ".#..",
    ".#..",
    ".##.",
    "....",
    "G..#",
]


class TestNeighbors:
    def test_center(self):
        grid = [["." for _ in range(3)] for _ in range(3)]
        assert set(neighbors(grid, (1, 1))) == {(0, 1), (2, 1), (1, 0), (1, 2)}

    def test_walls_and_bounds(self):
        rows = ["S#.", "..."]
        grid, _, _ = parse_grid(rows)
        assert set(neighbors(grid, (0, 0))) == {(1, 0)}  # wall right, edge up/left
        assert set(neighbors(grid, (0, 2))) == {(0, 1), (1, 2)}


class TestAstarBasic:
    def test_open_grid_optimal(self):
        rows = ["S...", "....", "....", "...G"]
        assert path_cost(astar(*parse_grid(rows))) == bfs_distance(rows) == 6

    def test_unreachable_returns_none(self):
        rows = ["S#G", "..."]
        assert astar(*parse_grid(rows)) is None

    def test_start_is_goal(self):
        rows = [".S.", "..."]
        grid, s, g = parse_grid(rows)
        assert astar(grid, s, s) == [s]

    def test_path_is_valid(self):
        grid, s, g = parse_grid(MAP_SUBOPTIMAL)
        path = astar(grid, s, g)
        assert path[0] == s and path[-1] == g
        for a, b in zip(path, path[1:]):
            assert abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1  # 4-connected step
            assert grid[b[0]][b[1]] != "#"


class TestRegressionSuboptimalPath:
    def test_matches_bfs_on_wall_trap_map(self):
        """Regression: the inadmissible 1.5*Euclidean heuristic returned a
        cost-10 path here where BFS proves the optimum is 8."""
        optimal = bfs_distance(MAP_SUBOPTIMAL)
        grid, s, g = parse_grid(MAP_SUBOPTIMAL)
        cost = path_cost(astar(grid, s, g))
        assert cost == optimal == 8

    @pytest.mark.parametrize("seed_map", [
        ["S.#G", "...#"],                      # tempting straight line blocked
        ["..S..", "#####", "..G..", "....."],
        ["S....", ".###.", ".....", ".###.", "....G"],
    ])
    def test_optimal_on_more_maps(self, seed_map):
        optimal = bfs_distance(seed_map)
        grid, s, g = parse_grid(seed_map)
        assert path_cost(astar(grid, s, g)) == optimal
"})
